    // ===== BREATHING EXERCISE =====
    const breathCircle = document.getElementById('breathCircle');
    const breathInstruction = document.getElementById('breathInstruction');
    const breathStart = document.getElementById('breathStart');
    const breathReset = document.getElementById('breathReset');

    let breathInterval = null;
    let breathPhase = 0; // 0: inhale, 1: hold, 2: exhale

    const breathPhases = [
      { text: 'Inhala', duration: 4000, color: '#22d3ee' },
      { text: 'Mantén', duration: 7000, color: '#8b5cf6' },
      { text: 'Exhala', duration: 8000, color: '#10b981' }
    ];

    function startBreathing() {
      if (breathInterval) clearInterval(breathInterval);

      breathPhase = 0;
      updateBreathDisplay();

      breathInterval = setInterval(() => {
        breathPhase = (breathPhase + 1) % 3;
        updateBreathDisplay();
      }, breathPhases[breathPhase].duration);

      breathStart.textContent = '⏸️ Pausar';
      breathStart.classList.add('active');
    }

    function pauseBreathing() {
      if (breathInterval) {
        clearInterval(breathInterval);
        breathInterval = null;
      }
      breathStart.textContent = '▶️ Reanudar';
      breathStart.classList.remove('active');
    }

    function resetBreathing() {
      if (breathInterval) clearInterval(breathInterval);
      breathInterval = null;
      breathPhase = 0;
      breathCircle.textContent = 'Inhala';
      breathCircle.style.background = 'linear-gradient(135deg, var(--accent-purple), var(--accent-cyan))';
      breathInstruction.textContent = 'Presiona "Iniciar" para comenzar';
      breathStart.textContent = '▶️ Iniciar';
      breathStart.classList.remove('active');
    }

    function updateBreathDisplay() {
      const phase = breathPhases[breathPhase];
      breathCircle.textContent = phase.text;
      breathCircle.style.background = `linear-gradient(135deg, ${phase.color}, var(--accent-purple))`;
      breathInstruction.textContent = `${phase.text}... (${phase.duration/1000}s)`;
    }

    breathStart.addEventListener('click', () => {
      if (breathInterval) {
        pauseBreathing();
      } else {
        startBreathing();
      }
    });

    breathReset.addEventListener('click', resetBreathing);

    // ===== CBT THOUGHT JOURNAL =====
    document.getElementById('saveCbt')?.addEventListener('click', () => {
      const entry = {
        situation: document.getElementById('cbtSituation').value.trim(),
        thought: document.getElementById('cbtThought').value.trim(),
        feeling: document.getElementById('cbtFeeling').value.trim(),
        evidence: document.getElementById('cbtEvidence').value.trim(),
        reframe: document.getElementById('cbtReframe').value.trim(),
        timestamp: new Date().toISOString()
      };

      // Save only if at least one field has content
      if (Object.values(entry).some(v => v)) {
        try {
          // Get existing entries or initialize array
          const existing = JSON.parse(localStorage.getItem('mindatlas_cbt') || '[]');
          existing.unshift(entry); // Add to beginning

          // Keep only last 20 entries to manage storage
          if (existing.length > 20) existing.pop();

          localStorage.setItem('mindatlas_cbt', JSON.stringify(existing));

          // Feedback
          const btn = document.getElementById('saveCbt');
          const original = btn.textContent;
          btn.textContent = '✅ Guardado (solo en este dispositivo)';
          btn.disabled = true;
          setTimeout(() => {
            btn.textContent = original;
            btn.disabled = false;
          }, 2500);
        } catch (e) {
          alert('⚠️ No se pudo guardar. ¿Navegador privado o almacenamiento lleno?');
          console.error('CBT save error:', e);
        }
      } else {
        alert('💡 Escribe al menos algo en un campo para guardar');
      }
    });

    // ===== NAVIGATION =====
    function scrollToSection(id) {
      document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    // ===== BUTTONS =====
    document.getElementById('aboutBtn')?.addEventListener('click', () => {
      alert(`🧠 MindAtlas Junior v2.0-MAX

