    }

    .card h3 {
      font-size: 1.3rem;
      margin-bottom: 0.75rem;
      color: var(--text-primary);
    }

    .card p {
      color: var(--text-secondary);
      font-size: 0.95rem;
      margin-bottom: 1rem;
    }

    .card-tag {
      display: inline-block;
      background: rgba(139,92,246,0.2);
      color: var(--accent-purple);
      padding: 0.25rem 0.75rem;
      border-radius: 20px;
      font-size: 0.8rem;
      font-weight: 600;
    }

    /* ===== MODAL ===== */
    .modal {
      display: none;
      position: fixed;
      top: 0; left: 0; width: 100%; height: 100%;
      background: rgba(0,0,0,0.8);
      z-index: 1000;
      justify-content: center;
      align-items: center;
      padding: 1rem;
      backdrop-filter: blur(5px);
    }

    .modal.active {
      display: flex;
    }

    .modal-content {
      background: var(--bg-secondary);
      border-radius: var(--border-radius);
      max-width: 700px;
      width: 100%;
      max-height: 90vh;
      overflow-y: auto;
      border: 1px solid var(--accent-purple);
      box-shadow: var(--shadow);
      position: relative;
      animation: modalSlide 0.3s ease;
    }

    @keyframes modalSlide {
      from { opacity: 0; transform: translateY(30px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .modal-header {
      padding: 1.5rem;
      border-bottom: 1px solid rgba(139,92,246,0.3);
      display: flex;
      justify-content: space-between;
      align-items: center;
      position: sticky;
      top: 0;
      background: var(--bg-secondary);
      z-index: 10;
    }

    .modal-close {
      background: none;
      border: none;
      color: var(--text-secondary);
      font-size: 1.5rem;
      cursor: pointer;
      width: 40px; height: 40px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: var(--transition);
    }

    .modal-close:hover {
      background: rgba(255,255,255,0.1);
      color: var(--text-primary);
    }

    .modal-body {
      padding: 1.5rem;
    }

    .modal-body h2 {
      margin-bottom: 1rem;
      color: var(--accent-cyan);
    }

    .modal-body ul {
      margin: 1rem 0;
      padding-left: 1.5rem;
    }

    .modal-body li {
      margin-bottom: 0.5rem;
      color: var(--text-secondary);
    }

    .science-note {
      background: rgba(34,211,238,0.1);
      border-left: 4px solid var(--accent-cyan);
      padding: 1rem;
      margin: 1.5rem 0;
      border-radius: 0 8px 8px 0;
      font-size: 0.95rem;
    }

    .science-note strong {
      color: var(--accent-cyan);
    }

    /* ===== INTERACTIVE TOOLS ===== */
    .tool-section {
      background: var(--bg-card);
      border-radius: var(--border-radius);
      padding: 2rem;
      margin: 2rem 0;
      border: 1px solid rgba(236,72,153,0.3);
    }

    .mood-tracker {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 0.75rem;
      margin: 1.5rem 0;
    }

    .mood-btn {
      aspect-ratio: 1;
      border: none;
      border-radius: 12px;
      font-size: 1.5rem;
      cursor: pointer;
      transition: var(--transition);
      background: var(--bg-secondary);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .mood-btn:hover, .mood-btn.selected {
      transform: scale(1.1);
      box-shadow: 0 5px 20px rgba(0,0,0,0.3);
    }

    .mood-btn:nth-child(1):hover { background: #ef4444; }
    .mood-btn:nth-child(2):hover { background: #f97316; }
    .mood-btn:nth-child(3):hover { background: #f59e0b; }
    .mood-btn:nth-child(4):hover { background: #22c55e; }
    .mood-btn:nth-child(5):hover { background: #3b82f6; }

    .journal-area {
      width: 100%;
      min-height: 120px;
      background: var(--bg-secondary);
      border: 1px solid rgba(139,92,246,0.3);
      border-radius: 12px;
      padding: 1rem;
      color: var(--text-primary);
      font-size: 1rem;
      resize: vertical;
      margin: 1rem 0;
    }

    .journal-area:focus {
      outline: none;
      border-color: var(--accent-purple);
      box-shadow: 0 0 0 3px rgba(139,92,246,0.3);
    }

    /* ===== CRISIS BANNER ===== */
    .crisis-banner {
      background: linear-gradient(135deg, rgba(239,68,68,0.2), rgba(249,115,22,0.2));
      border: 1px solid var(--danger);
      border-radius: var(--border-radius);
      padding: 1.5rem;
      margin: 2rem 0;
      text-align: center;
    }

    .crisis-banner h3 {
      color: var(--danger);
      margin-bottom: 0.75rem;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
    }

    .crisis-numbers {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 1rem;
      margin-top: 1rem;
    }

    .crisis-number {
      background: rgba(239,68,68,0.2);
      padding: 0.75rem 1.5rem;
      border-radius: 50px;
      font-weight: 700;
      font-size: 1.1rem;
    }

    .crisis-number span {
      display: block;
      font-size: 0.85rem;
      font-weight: 400;
      color: var(--text-secondary);
      margin-top: 0.25rem;
    }

    /* ===== FOOTER ===== */
    footer {
      text-align: center;
      padding: 2rem;
      margin-top: 3rem;
      border-top: 1px solid rgba(139,92,246,0.2);
      color: var(--text-secondary);
      font-size: 0.9rem;
    }

    .privacy-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      background: rgba(16,185,129,0.15);
      color: var(--success);
      padding: 0.4rem 1rem;
      border-radius: 50px;
      font-size: 0.85rem;
      margin: 1rem 0;
    }

    .sources {
      margin-top: 1rem;
      font-size: 0.85rem;
    }

    .sources a {
      color: var(--accent-cyan);
      text-decoration: none;
    }

    .sources a:hover {
      text-decoration: underline;
    }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 768px) {
      .hero h1 { font-size: 2.2rem; }
      .mood-tracker { grid-template-columns: repeat(5, 1fr); }
      .cards-grid { grid-template-columns: 1fr; }
      header { padding: 1rem; flex-wrap: wrap; gap: 0.75rem; }
    }

    /* ===== UTILS ===== */
    .hidden { display: none !important; }
    .text-center { text-align: center; }
    .mt-2 { margin-top: 2rem; }
    .mb-1 { margin-bottom: 1rem; }
    .fade-in { animation: fadeIn 0.4s ease; }

    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(10px); }
      to { opacity: 1; transform: translateY(0); }
    }

    /* ===== AI COPilot BADGE ===== */
    .ai-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      background: linear-gradient(135deg, rgba(139,92,246,0.2), rgba(236,72,153,0.2));
      padding: 0.3rem 0.8rem;
      border-radius: 20px;
      font-size: 0.8rem;
      margin-left: 0.5rem;
      border: 1px solid var(--accent-purple);
    }

    .ai-badge::before {
      content: "✨";
    }
  </style>
</head>
<body>
  <!-- Background Effects -->
  <div class="bg-animation"></div>
  <div class="particles" id="particles"></div>

  <!-- Header -->
  <header>
    <div class="logo">
      <span class="logo-icon">🧠</span>
      MindAtlas Junior
    </div>
    <div class="nav-actions">
      <button class="btn btn-outline" id="aboutBtn">ℹ️ Sobre esto</button>
      <button class="btn btn-crisis" id="crisisBtn">🆘 Ayuda Urgente</button>
    </div>
  </header>

  <!-- Hero Section -->
  <section class="hero">
    <div class="disclaimer-badge">
