# 🌟 MINDATLAS JUNIOR - VERSIÓN MÁXIMA 🌟
## Aplicación Web Completa de Salud Mental para Menores

```html
<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no"/>
  <meta name="description" content="MindAtlas Junior: Educación en salud mental basada en evidencia para jóvenes 10-19 años. Información científica, 100% privada, sin servidores."/>
  <meta name="theme-color" content="#7c3aed"/>
  <meta name="apple-mobile-web-app-capable" content="yes"/>
  <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"/>
  <title>🧠 MindAtlas Junior | Tu Espacio Científico y Seguro</title>
  <style>
    /* ===== CORE VARIABLES ===== */
    :root {
      /* Colors - Dark Mode with Youth Appeal */
      --bg-primary: #0a0514;
      --bg-secondary: #140e24;
      --bg-card: #1f1635;
      --bg-elevated: #2a2045;
      --text-primary: #ffffff;
      --text-secondary: #c7b8e8;
      --text-muted: #8b7aa8;

      /* Accent Palette */
      --accent-purple: #8b5cf6;
      --accent-purple-light: #a78bfa;
      --accent-pink: #ec4899;
      --accent-cyan: #22d3ee;
      --accent-teal: #14b8a6;
      --accent-amber: #f59e0b;

      /* Semantic Colors */
      --success: #10b981;
      --warning: #f59e0b;
      --danger: #ef4444;
      --info: #3b82f6;

      /* Layout */
      --radius-sm: 8px;
      --radius-md: 16px;
      --radius-lg: 24px;
      --radius-full: 9999px;
      --shadow-sm: 0 2px 8px rgba(0,0,0,0.3);
      --shadow-md: 0 8px 32px rgba(0,0,0,0.4);
      --shadow-lg: 0 16px 64px rgba(0,0,0,0.5);
      --transition: all 0.25s cubic-bezier(0.4,0,0.2,1);

      /* Typography */
      --font-sans: 'Segoe UI', system-ui, -apple-system, sans-serif;
      --font-mono: 'SF Mono', 'Fira Code', monospace;
    }

    /* ===== RESET & BASE ===== */
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font-sans);
      background: var(--bg-primary);
      color: var(--text-primary);
      line-height: 1.6;
      min-height: 100vh;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    /* ===== BACKGROUND ANIMATION ===== */
    .bg-gradient {
      position: fixed;
      inset: 0;
      z-index: -2;
      background: 
        radial-gradient(ellipse at 15% 85%, rgba(139,92,246,0.12) 0%, transparent 55%),
        radial-gradient(ellipse at 85% 15%, rgba(236,72,153,0.10) 0%, transparent 55%),
        radial-gradient(ellipse at 50% 50%, rgba(34,211,238,0.06) 0%, transparent 70%);
      animation: gradientShift 20s ease-in-out infinite;
    }

    @keyframes gradientShift {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.85; }
    }

    .particles {
      position: fixed;
      inset: 0;
      z-index: -1;
      pointer-events: none;
      overflow: hidden;
    }

    .particle {
      position: absolute;
      width: 3px; height: 3px;
      border-radius: 50%;
      background: var(--accent-purple-light);
      opacity: 0.5;
      animation: float 18s infinite ease-in-out;
      will-change: transform;
    }

    @keyframes float {
      0%, 100% { transform: translateY(0) translateX(0) scale(1); opacity: 0.5; }
      25% { transform: translateY(-25px) translateX(15px) scale(1.1); opacity: 0.8; }
      50% { transform: translateY(-10px) translateX(-10px) scale(0.9); opacity: 0.6; }
      75% { transform: translateY(-35px) translateX(20px) scale(1.05); opacity: 0.7; }
    }

    /* ===== HEADER ===== */
    header {
      position: sticky;
      top: 0;
      z-index: 100;
      padding: 1rem 1.5rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      background: rgba(10,5,20,0.92);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(139,92,246,0.25);
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 0.6rem;
      font-weight: 800;
      font-size: 1.3rem;
      background: linear-gradient(135deg, var(--accent-purple), var(--accent-pink), var(--accent-cyan));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-size: 200% 200%;
      animation: shine 8s ease-in-out infinite;
    }

    @keyframes shine {
      0%, 100% { background-position: 0% 50%; }
      50% { background-position: 100% 50%; }
    }

    .logo-icon { font-size: 1.5rem; }

    .header-actions {
      display: flex;
      gap: 0.5rem;
      align-items: center;
    }

    /* ===== BUTTONS ===== */
    .btn {
      padding: 0.6rem 1.2rem;
      border: none;
      border-radius: var(--radius-full);
      font-weight: 600;
      font-size: 0.9rem;
      cursor: pointer;
      transition: var(--transition);
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      text-decoration: none;
      white-space: nowrap;
    }

    .btn:focus-visible {
      outline: 2px solid var(--accent-cyan);
      outline-offset: 2px;
    }

    .btn-primary {
      background: linear-gradient(135deg, var(--accent-purple), var(--accent-pink));
      color: white;
      box-shadow: 0 4px 20px rgba(139,92,246,0.35);
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 6px 28px rgba(139,92,246,0.55);
    }

    .btn-outline {
      background: transparent;
      border: 2px solid var(--accent-purple-light);
      color: var(--text-primary);
    }

    .btn-outline:hover {
      background: rgba(139,92,246,0.15);
    }

    .btn-crisis {
      background: linear-gradient(135deg, var(--danger), #f97316);
      color: white;
      animation: pulse-crisis 2.5s infinite;
      font-weight: 700;
    }

    @keyframes pulse-crisis {
      0%, 100% { box-shadow: 0 0 0 0 rgba(239,68,68,0.6); }
      50% { box-shadow: 0 0 0 14px rgba(239,68,68,0); }
    }

    .btn-icon {
      width: 40px; height: 40px;
      border-radius: var(--radius-full);
      display: flex;
      align-items: center;
      justify-content: center;
      background: var(--bg-elevated);
      border: 1px solid rgba(139,92,246,0.3);
      color: var(--text-primary);
      font-size: 1.2rem;
      cursor: pointer;
      transition: var(--transition);
    }

    .btn-icon:hover {
      background: var(--accent-purple);
      transform: scale(1.05);
    }

    /* ===== HERO SECTION ===== */
    .hero {
      padding: 2.5rem 1.5rem 2rem;
      text-align: center;
      max-width: 900px;
      margin: 0 auto;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      background: rgba(245,158,11,0.12);
      border: 1px solid var(--warning);
      color: var(--warning);
      padding: 0.5rem 1rem;
      border-radius: var(--radius-full);
      font-size: 0.85rem;
      font-weight: 600;
      margin-bottom: 1.2rem;
      animation: fadeInUp 0.5s ease;
    }

    .hero h1 {
      font-size: clamp(2rem, 5vw, 2.8rem);
      margin-bottom: 1rem;
      line-height: 1.15;
      background: linear-gradient(135deg, var(--text-primary), var(--accent-cyan), var(--accent-purple-light));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      animation: fadeInUp 0.6s ease 0.1s both;
    }

    .hero p {
      font-size: 1.1rem;
      color: var(--text-secondary);
      margin-bottom: 1.8rem;
      max-width: 700px;
      margin-left: auto;
      margin-right: auto;
      animation: fadeInUp 0.6s ease 0.2s both;
    }

    .hero-actions {
      display: flex;
      gap: 1rem;
      justify-content: center;
      flex-wrap: wrap;
      animation: fadeInUp 0.6s ease 0.3s both;
    }

    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(20px); }
      to { opacity: 1; transform: translateY(0); }
    }

    /* ===== CRISIS BANNER ===== */
    .crisis-banner {
      background: linear-gradient(135deg, rgba(239,68,68,0.15), rgba(249,115,22,0.12));
      border: 1px solid var(--danger);
      border-radius: var(--radius-lg);
      padding: 1.5rem;
      margin: 1rem 1.5rem 2rem;
      text-align: center;
      animation: slideIn 0.4s ease;
    }

    @keyframes slideIn {
      from { opacity: 0; transform: translateY(-10px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .crisis-banner h3 {
      color: var(--danger);
      margin-bottom: 0.75rem;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      font-size: 1.2rem;
    }

    .crisis-banner p {
      color: var(--text-secondary);
      margin-bottom: 1rem;
      font-size: 0.95rem;
    }

    .crisis-numbers {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 0.75rem;
    }

    .crisis-number {
      background: rgba(239,68,68,0.15);
      padding: 0.75rem 1.2rem;
      border-radius: var(--radius-md);
      font-weight: 700;
      font-size: 1.05rem;
      min-width: 180px;
      transition: var(--transition);
    }

    .crisis-number:hover {
      background: rgba(239,68,68,0.25);
      transform: translateY(-2px);
    }

    .crisis-number span {
      display: block;
      font-size: 0.8rem;
      font-weight: 400;
      color: var(--text-muted);
      margin-top: 0.25rem;
    }

    .crisis-number a {
      color: inherit;
      text-decoration: none;
    }

    .crisis-number a:hover {
      text-decoration: underline;
    }

    /* ===== MAIN CONTENT ===== */
    main {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 1.5rem 3rem;
    }

    .section {
      margin: 3rem 0;
      animation: fadeIn 0.5s ease;
    }

    @keyframes fadeIn {
      from { opacity: 0; }
      to { opacity: 1; }
    }

    .section-header {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      margin-bottom: 1.5rem;
      padding-bottom: 0.75rem;
      border-bottom: 2px solid rgba(139,92,246,0.3);
    }

    .section-header h2 {
      font-size: 1.7rem;
      color: var(--text-primary);
    }

    .section-subtitle {
      color: var(--text-secondary);
      margin-bottom: 1.5rem;
      font-size: 1.05rem;
      max-width: 800px;
    }

    /* ===== CARDS GRID ===== */
    .cards-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 1.2rem;
    }

    .card {
      background: var(--bg-card);
      border-radius: var(--radius-lg);
      padding: 1.5rem;
      border: 1px solid rgba(139,92,246,0.2);
      transition: var(--transition);
      cursor: pointer;
      display: flex;
      flex-direction: column;
      gap: 1rem;
    }

    .card:hover {
      transform: translateY(-4px);
      border-color: var(--accent-purple);
      box-shadow: var(--shadow-md);
    }

    .card:focus-within {
      outline: 2px solid var(--accent-cyan);
      outline-offset: 2px;
    }

    .card-icon {
      font-size: 2rem;
      display: block;
    }

    .card h3 {
      font-size: 1.25rem;
      color: var(--text-primary);
      margin-bottom: 0.25rem;
    }

    .card p {
      color: var(--text-secondary);
      font-size: 0.95rem;
      flex-grow: 1;
    }

    .card-footer {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      flex-wrap: wrap;
    }

    .card-tag {
      display: inline-flex;
      align-items: center;
      gap: 0.3rem;
      background: rgba(139,92,246,0.15);
      color: var(--accent-purple-light);
      padding: 0.25rem 0.75rem;
      border-radius: var(--radius-full);
      font-size: 0.75rem;
      font-weight: 600;
    }

    .card-tag.success { background: rgba(16,185,129,0.15); color: var(--success); }
    .card-tag.warning { background: rgba(245,158,11,0.15); color: var(--warning); }
    .card-tag.info { background: rgba(59,130,246,0.15); color: var(--info); }

    /* ===== MODAL SYSTEM ===== */
    .modal {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.85);
      z-index: 1000;
      justify-content: center;
      align-items: center;
      padding: 1rem;
      backdrop-filter: blur(4px);
    }

    .modal.active { display: flex; animation: modalFadeIn 0.3s ease; }

    @keyframes modalFadeIn {
      from { opacity: 0; }
      to { opacity: 1; }
    }

    .modal-content {
      background: var(--bg-secondary);
      border-radius: var(--radius-lg);
      max-width: 750px;
      width: 100%;
      max-height: 92vh;
      overflow-y: auto;
      border: 1px solid var(--accent-purple);
      box-shadow: var(--shadow-lg);
      position: relative;
      animation: modalSlide 0.35s ease;
    }

    @keyframes modalSlide {
      from { opacity: 0; transform: translateY(25px) scale(0.98); }
      to { opacity: 1; transform: translateY(0) scale(1); }
    }

    .modal-header {
      padding: 1.25rem 1.5rem;
      border-bottom: 1px solid rgba(139,92,246,0.25);
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 1rem;
      position: sticky;
      top: 0;
      background: var(--bg-secondary);
      z-index: 10;
      border-radius: var(--radius-lg) var(--radius-lg) 0 0;
    }

    .modal-header h2 {
      font-size: 1.4rem;
      color: var(--accent-cyan);
      line-height: 1.3;
    }

    .modal-close {
      background: none;
      border: none;
      color: var(--text-muted);
      font-size: 1.8rem;
      cursor: pointer;
      width: 40px; height: 40px;
      border-radius: var(--radius-full);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: var(--transition);
      flex-shrink: 0;
    }

    .modal-close:hover {
      background: rgba(255,255,255,0.1);
      color: var(--text-primary);
    }

    .modal-body {
      padding: 1.25rem 1.5rem 2rem;
    }

    .modal-body h3 {
      margin: 1.5rem 0 0.75rem;
      color: var(--accent-purple-light);
      font-size: 1.2rem;
    }

    .modal-body p {
      color: var(--text-secondary);
      margin-bottom: 0.75rem;
      font-size: 1rem;
    }

    .modal-body ul {
      margin: 0.75rem 0 1rem 1.5rem;
      color: var(--text-secondary);
    }

    .modal-body li {
      margin-bottom: 0.4rem;
    }

    .modal-body strong {
      color: var(--text-primary);
    }

    /* ===== SCIENCE NOTE ===== */
    .science-note {
      background: linear-gradient(135deg, rgba(34,211,238,0.1), rgba(139,92,246,0.08));
      border-left: 4px solid var(--accent-cyan);
      padding: 1rem 1.25rem;
      margin: 1.25rem 0;
      border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
      font-size: 0.95rem;
    }

    .science-note strong {
      color: var(--accent-cyan);
      display: block;
      margin-bottom: 0.4rem;
    }

    .source-citation {
      display: inline-block;
      background: rgba(139,92,246,0.2);
      color: var(--accent-purple-light);
      padding: 0.15rem 0.5rem;
      border-radius: 4px;
      font-size: 0.75rem;
      font-weight: 600;
      margin-left: 0.3rem;
      text-decoration: none;
    }

    .source-citation:hover {
      background: var(--accent-purple);
      color: white;
    }

    /* ===== INTERACTIVE TOOLS ===== */
    .tool-section {
      background: var(--bg-card);
      border-radius: var(--radius-lg);
      padding: 1.75rem;
      margin: 1.5rem 0;
      border: 1px solid rgba(236,72,153,0.25);
    }

    .tool-section h3 {
      margin-bottom: 0.5rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    .tool-description {
      color: var(--text-secondary);
      margin-bottom: 1.25rem;
      font-size: 0.95rem;
    }

    /* Mood Tracker */
    .mood-tracker {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 0.6rem;
      margin: 1.25rem 0;
    }

    .mood-btn {
      aspect-ratio: 1;
      border: 2px solid transparent;
      border-radius: var(--radius-md);
      font-size: 1.6rem;
      cursor: pointer;
      transition: var(--transition);
      background: var(--bg-elevated);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
    }

    .mood-btn::after {
      content: attr(title);
      position: absolute;
      bottom: -28px;
      left: 50%;
      transform: translateX(-50%);
      background: var(--bg-elevated);
      color: var(--text-primary);
      padding: 0.2rem 0.5rem;
      border-radius: 4px;
      font-size: 0.7rem;
      white-space: nowrap;
      opacity: 0;
      pointer-events: none;
      transition: var(--transition);
    }

    .mood-btn:hover::after { opacity: 1; bottom: -32px; }

    .mood-btn:hover, .mood-btn.selected {
      transform: scale(1.08);
      border-color: var(--accent-purple);
      box-shadow: 0 4px 16px rgba(139,92,246,0.3);
    }

    .mood-btn:nth-child(1):hover { background: #ef4444; }
    .mood-btn:nth-child(2):hover { background: #f97316; }
    .mood-btn:nth-child(3):hover { background: #f59e0b; }
    .mood-btn:nth-child(4):hover { background: #22c55e; }
    .mood-btn:nth-child(5):hover { background: #3b82f6; }

    /* Journal */
    .journal-area {
      width: 100%;
      min-height: 100px;
      background: var(--bg-elevated);
      border: 1px solid rgba(139,92,246,0.25);
      border-radius: var(--radius-md);
      padding: 1rem;
      color: var(--text-primary);
      font-size: 1rem;
      font-family: inherit;
      resize: vertical;
      margin: 1rem 0;
      transition: var(--transition);
    }

    .journal-area:focus {
      outline: none;
      border-color: var(--accent-purple);
      box-shadow: 0 0 0 3px rgba(139,92,246,0.25);
    }

    .journal-area::placeholder {
      color: var(--text-muted);
    }

    /* Coping Skills Library */
    .coping-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
      gap: 0.75rem;
      margin: 1rem 0;
    }

    .coping-card {
      background: var(--bg-elevated);
      border-radius: var(--radius-md);
      padding: 1rem;
      text-align: center;
      cursor: pointer;
      transition: var(--transition);
      border: 1px solid transparent;
    }

    .coping-card:hover, .coping-card.active {
      border-color: var(--accent-cyan);
      background: rgba(34,211,238,0.1);
      transform: translateY(-2px);
    }

    .coping-card-icon {
      font-size: 1.8rem;
      margin-bottom: 0.5rem;
      display: block;
    }

    .coping-card-title {
      font-weight: 600;
      font-size: 0.9rem;
      margin-bottom: 0.25rem;
    }

    .coping-card-desc {
      font-size: 0.75rem;
      color: var(--text-muted);
    }

    /* Breathing Exercise */
    .breathing-container {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 1.5rem;
      padding: 1rem;
    }

    .breathing-circle {
      width: 120px;
      height: 120px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--accent-purple), var(--accent-cyan));
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 1.1rem;
      color: white;
      animation: breathe 8s infinite ease-in-out;
      box-shadow: 0 0 40px rgba(139,92,246,0.5);
    }

    @keyframes breathe {
      0%, 100% { transform: scale(1); opacity: 0.9; }
      50% { transform: scale(1.35); opacity: 1; }
    }

    .breathing-instruction {
      text-align: center;
      font-size: 1.1rem;
      min-height: 2rem;
      color: var(--accent-cyan);
      font-weight: 600;
    }

    .breathing-timer {
      display: flex;
      gap: 0.5rem;
      justify-content: center;
    }

    .breathing-btn {
      padding: 0.5rem 1rem;
      background: var(--bg-elevated);
      border: 1px solid var(--accent-purple);
      border-radius: var(--radius-full);
      color: var(--text-primary);
      cursor: pointer;
      transition: var(--transition);
      font-size: 0.9rem;
    }

    .breathing-btn:hover, .breathing-btn.active {
      background: var(--accent-purple);
    }

    /* Thought Journal (CBT) */
    .cbt-journal {
      display: grid;
      gap: 1rem;
    }

    .cbt-field {
      display: flex;
      flex-direction: column;
      gap: 0.4rem;
    }

    .cbt-field label {
      font-size: 0.9rem;
      font-weight: 600;
      color: var(--accent-purple-light);
    }

    .cbt-field textarea {
      min-height: 70px;
      padding: 0.75rem;
      background: var(--bg-elevated);
      border: 1px solid rgba(139,92,246,0.25);
      border-radius: var(--radius-md);
      color: var(--text-primary);
      font-size: 0.95rem;
      font-family: inherit;
      resize: vertical;
    }

    .cbt-field textarea:focus {
      outline: none;
      border-color: var(--accent-cyan);
      box-shadow: 0 0 0 3px rgba(34,211,238,0.2);
    }

    /* ===== PRIVACY CARDS ===== */
    .privacy-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
      gap: 1rem;
      margin-top: 1rem;
    }

    .privacy-card {
      background: var(--bg-elevated);
      border-radius: var(--radius-md);
      padding: 1.25rem;
      text-align: center;
      border: 1px solid rgba(139,92,246,0.2);
    }

    .privacy-icon {
      font-size: 2rem;
      margin-bottom: 0.75rem;
      display: block;
    }

    .privacy-card h4 {
      margin-bottom: 0.5rem;
      font-size: 1.1rem;
    }

    .privacy-card p {
      font-size: 0.9rem;
      color: var(--text-secondary);
    }

    .privacy-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      background: rgba(16,185,129,0.15);
      color: var(--success);
      padding: 0.4rem 1rem;
      border-radius: var(--radius-full);
      font-size: 0.85rem;
      font-weight: 600;
      margin: 1rem 0;
    }

    /* ===== ALGEE GUIDE ===== */
    .algee-step {
      background: var(--bg-elevated);
      border-radius: var(--radius-md);
      padding: 1rem;
      margin: 0.75rem 0;
      border-left: 3px solid var(--accent-purple);
    }

    .algee-step h4 {
      color: var(--accent-purple-light);
      margin-bottom: 0.4rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    .algee-step ul {
      margin-left: 1.25rem;
      color: var(--text-secondary);
      font-size: 0.95rem;
    }

    .algee-step li {
      margin-bottom: 0.3rem;
    }

    /* ===== FOOTER ===== */
    footer {
      text-align: center;
      padding: 2.5rem 1.5rem 3rem;
      margin-top: 2rem;
      border-top: 1px solid rgba(139,92,246,0.2);
      color: var(--text-secondary);
      font-size: 0.9rem;
    }

    footer .privacy-badge {
      margin: 1rem 0;
    }

    footer p {
      margin: 0.5rem 0;
    }

    .sources {
      margin-top: 1.2rem;
      font-size: 0.85rem;
      line-height: 1.5;
    }

    .sources a {
      color: var(--accent-cyan);
      text-decoration: none;
    }

    .sources a:hover {
      text-decoration: underline;
    }

    .version {
      margin-top: 1rem;
      font-size: 0.8rem;
      opacity: 0.7;
    }

    /* ===== AI BADGE ===== */
    .ai-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.35rem;
      background: linear-gradient(135deg, rgba(139,92,246,0.2), rgba(236,72,153,0.15));
      padding: 0.25rem 0.7rem;
      border-radius: var(--radius-full);
      font-size: 0.75rem;
      font-weight: 600;
      margin-left: 0.4rem;
      border: 1px solid var(--accent-purple);
      vertical-align: middle;
    }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 768px) {
      .hero h1 { font-size: 2rem; }
      .mood-tracker { grid-template-columns: repeat(5, 1fr); }
      .cards-grid { grid-template-columns: 1fr; }
      .header-actions { gap: 0.3rem; }
      .btn { padding: 0.5rem 1rem; font-size: 0.85rem; }
      .crisis-numbers { flex-direction: column; align-items: center; }
      .crisis-number { width: 100%; max-width: 300px; }
    }

    @media (max-width: 480px) {
      header { padding: 0.75rem 1rem; }
      .logo { font-size: 1.15rem; }
      .hero { padding: 2rem 1rem 1.5rem; }
      .section-header h2 { font-size: 1.4rem; }
      .modal-content { max-height: 95vh; }
      .modal-header h2 { font-size: 1.2rem; }
    }

    /* ===== UTILITIES ===== */
    .hidden { display: none !important; }
    .text-center { text-align: center; }
    .mt-1 { margin-top: 1rem; }
    .mt-2 { margin-top: 2rem; }
    .mb-1 { margin-bottom: 1rem; }
    .fade-in { animation: fadeIn 0.4s ease; }

    .sr-only {
      position: absolute;
      width: 1px; height: 1px;
      padding: 0; margin: -1px;
      overflow: hidden; clip: rect(0,0,0,0);
      white-space: nowrap; border: 0;
    }

    /* ===== PRINT STYLES ===== */
    @media print {
      .bg-gradient, .particles, header, footer, .btn, .crisis-banner { display: none !important; }
      body { background: white; color: black; }
      .modal { position: static; display: block !important; }
      .modal-content { box-shadow: none; border: none; max-height: none; }
    }
  </style>
</head>
<body>
  <!-- Background Effects -->
  <div class="bg-gradient"></div>
