    function openModal(key) {
      if (modalContent[key]) {
        // Save last focused element for accessibility
        lastFocusedElement = document.activeElement;

        modalTitle.textContent = modalContent[key].title;
        modalBody.innerHTML = modalContent[key].body;
        modal.classList.add('active');
        document.body.style.overflow = 'hidden'; // Prevent background scroll

        // Focus modal for accessibility
        modal.querySelector('.modal-close')?.focus();

        // Trap focus within modal (basic implementation)
        modal.focus();
      }
    }

    function closeModal() {
      modal.classList.remove('active');
      document.body.style.overflow = '';

      // Return focus to last element
      if (lastFocusedElement && typeof lastFocusedElement.focus === 'function') {
        lastFocusedElement.focus();
      }
    }

    // Close modal when clicking outside content
    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeModal();
    });

    // Close with Escape key
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && modal.classList.contains('active')) {
        closeModal();
      }
    });

