              btn.classList.remove('selected');
              btn.setAttribute('aria-checked', 'false');
            }
          });
          // Load journal text
          if (data.journal) journalArea.value = data.journal;
          saveStatus.textContent = `Último registro: ${new Date(data.timestamp).toLocaleDateString('es-ES', { 
            year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' 
